style.css:
/* transparent main background */
body {
  color: #754b5b !important;
}

/* soft rounded images */
img {
  border-radius: 12px !important;
}

/* pink scrollbars */
::-webkit-scrollbar-thumb {
  background: #eab5c9 !important;
  border-radius: 20px !important;
}

::-webkit-scrollbar-track {
  background: rgba(255, 244, 247, 0.5) !important;
}
